'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var dlansb = require( './../lib' );

// Define the upper triangular band storage (K=1) of a 4x4 symmetric band matrix in column-major order:
var AB = new Float64Array( [ 0.0, 2.0, 1.0, 3.0, 4.0, 5.0, 6.0, 7.0 ] );

// Allocate a workspace array (used when computing the one and infinity norms):
var work = new Float64Array( 4 );

// Compute the maximum absolute value of any element:
var out = dlansb( 'column-major', 'max', 'upper', 4, 1, AB, 2, work );
console.log( 'max: %d', out );

// Compute the one norm (maximum column sum):
out = dlansb( 'column-major', 'one', 'upper', 4, 1, AB, 2, work );
console.log( 'one: %d', out );

// Compute the infinity norm (maximum row sum):
out = dlansb( 'column-major', 'inf', 'upper', 4, 1, AB, 2, work );
console.log( 'inf: %d', out );

// Compute the Frobenius norm:
out = dlansb( 'column-major', 'fro', 'upper', 4, 1, AB, 2, work );
console.log( 'fro: %d', out );
